const FILE = 'input-1/TidalStaking.sol';
const FILE_SHA256 = '2d204875f7988682a091a4ccc04419315f5b040754669d9aa737f49b22494f07';

const UPDATE_REWARD_SOURCE = `modifier updateReward(address account) {
    rewardPerTokenStored = rewardPerToken();
    lastUpdateTime = lastTimeRewardApplicable();
    // Accounts with no stake have nothing accruing, so skip the two SSTOREs.
    if (account != address(0) && balanceOf[account] != 0) {
        rewards[account] = earned(account);
        userRewardPerTokenPaid[account] = rewardPerTokenStored;
    }
    _;
}`;

const CHECKPOINT_TEST = `function test_freshStakerEarnsNothingAtStake() public {
    vm.prank(alice);
    staking.stake(100e18);
    staking.notifyReward{value: 7 ether}();
    vm.warp(block.timestamp + 3 days);

    vm.prank(mallory);
    staking.stake(200e18);

    assertEq(staking.earned(mallory), 0);
}`;

const checkpointFinding = {
  id: 'F-1',
  title: 'A first stake is credited with the whole reward history',
  severity: 'critical',
  basis: 'proven-in-source',
  locations: [
    { label: FILE, start: 60, end: 69 },
    { label: FILE, start: 87, end: 90 },
    { label: FILE, start: 93, end: 105 },
  ],
  impact:
    'A new staker is paid as if staked since the first reward period. One transaction takes up to the whole ETH balance of the contract, which is owed to existing stakers.',
  path: [
    '`updateReward` writes `userRewardPerTokenPaid[account]` only when `balanceOf[account] != 0` (line 64). The checkpoint of a first-time staker stays 0.',
    '`stake` runs the modifier while the balance is still 0, then raises the balance at line 103.',
    '`earned()` multiplies the new balance by `rewardPerToken() - 0`, the whole accumulator (lines 87-90).',
    'With 7 ETH streaming over 7 days and 100 TIDE staked for 3 days, a fresh account stakes 200 TIDE and is credited 5.99 ETH. `claim` pays it and `unstake` returns the 200 TIDE in the same block.',
  ],
  counterargument: {
    objection: 'Accounts with no stake have nothing accruing, so skipping the two writes is safe.',
    status: 'resolved',
    why: 'The skipped write is the checkpoint, not the accrual. The comment at line 63 holds until line 103 raises the balance. After that `earned()` reads a checkpoint that was never set.',
  },
  gap: ['No test was run. The 5.99 ETH figure follows from the arithmetic at lines 84-89, not from an execution.'],
  fix: 'Remove `balanceOf[account] != 0` from line 64 and keep `account != address(0)`. Every interaction then sets the checkpoint.',
  test: { code: CHECKPOINT_TEST, name: 'test/TidalStaking.t.sol', numbers: false, copy: true },
  next: 'Run the test against the current contract, apply the fix, and run it again.',
};

const reentrancyFinding = {
  id: 'F-2',
  title: '`claim` pays before it clears, and `exit` has no reentrancy guard',
  severity: 'high',
  basis: 'proven-in-source',
  locations: [
    { label: FILE, start: 119, end: 125 },
    { label: FILE, start: 128, end: 142 },
    { label: FILE, start: 170, end: 173 },
  ],
  impact:
    'A staking contract collects its accrued reward twice per cycle. The second payment comes from ETH owed to other stakers. The gain is one extra copy of the caller’s own accrued reward, repeatable each time rewards accrue.',
  path: [
    '`claim` sends ETH at line 122 and zeroes `rewards[msg.sender]` at line 123.',
    '`_sendEth` uses a plain `call`, which hands control to the receiver (lines 170-173).',
    'The receiver calls `exit`. It is not `nonReentrant` (line 128), reads the uncleared reward at line 130 and pays it again at line 139.',
  ],
  counterargument: {
    objection: '`claim` is `nonReentrant`, so the callback cannot re-enter.',
    status: 'resolved',
    why: 'The guard covers `claim`, `stake` and `unstake`. `exit` at line 128 does not carry it.',
  },
  gap: ['A receiver contract that calls `exit` from `receive()` has not been written or run.'],
  fix: 'Zero `rewards[msg.sender]` before `_sendEth` in `claim`, and add `nonReentrant` to `exit`.',
  next: 'Write the receiver contract and assert that it is paid once.',
};

const unratedFinding = {
  id: 'F-3',
  title: 'Rewards streamed while nothing is staked stay in the contract',
  severity: 'unrated',
  basis: 'needs-test',
  locations: [{ label: FILE, start: 81, end: 85 }],
  impact: 'ETH notified during a period with `totalStaked == 0` is never distributed. There is no function to recover it.',
  counterargument: {
    objection: 'The operator only funds a period once stakers exist.',
    status: 'open',
    why: 'Nothing supplied states when `notifyReward` is called. The deployment plan would settle it.',
  },
  gap: ['Deployment and funding order', 'Whether stranded ETH is in scope for the programme'],
  next: 'Ask the operator for the funding sequence before rating this.',
};

