function kitSection(id, title, lede, content) {
  return html`
<section class="kit__section" aria-labelledby="${id}">
  ${sectionHeading({ title, lede, id })}
  ${content}
</section>`;
}

function demo(label, content, { className } = {}) {
  return html`
<div class="kit__demo${className ? ` ${className}` : ''}">
  <p class="meta">${label}</p>
  <div class="kit__stage">${content}</div>
</div>`;
}

function swatch(token, note) {
  return html`<li class="swatch" data-token="${token}"><span class="swatch__chip"></span><span class="swatch__name">--${token}</span><span class="swatch__note">${note}</span></li>`;
}

